describe('API Error Banner Display', () => {
  beforeEach(() => {
    cy.visit('/dashboard');
  });

  it('should display error banner when API call fails', () => {
    // Intercept the API call and mock a failure response
    cy.intercept('GET', '/api/user-data', {
      statusCode: 500,
      body: { error: 'Internal Server Error' }
    }).as('apiCall');

    // Trigger the API call
    cy.get('[data-testid="load-user-data-button"]').click();

    // Wait for the API call to complete
    cy.wait('@apiCall');

    // Verify error banner is visible
    cy.get('[data-testid="error-banner"]').should('be.visible');

    // Verify error message is displayed
    cy.get('[data-testid="error-banner"]').should('contain', 'Failed to load user data');

    // Verify error banner has appropriate styling
    cy.get('[data-testid="error-banner"]').should('have.class', 'error-message');

    // Verify error banner has a close button
    cy.get('[data-testid="error-banner"]').find('[data-testid="close-error-button"]').should('be.visible');

    // Verify error banner is not hidden by default
    cy.get('[data-testid="error-banner"]').should('not.have.css', 'display', 'none');
  });

  it('should hide error banner when user dismisses it', () => {
    // Intercept the API call and mock a failure response
    cy.intercept('GET', '/api/user-data', {
      statusCode: 500,
      body: { error: 'Internal Server Error' }
    }).as('apiCall');

    // Trigger the API call
    cy.get('[data-testid="load-user-data-button"]').click();

    // Wait for the API call to complete
    cy.wait('@apiCall');

    // Verify error banner is visible
    cy.get('[data-testid="error-banner"]').should('be.visible');

    // Dismiss the error banner
    cy.get('[data-testid="error-banner"]').find('[data-testid="close-error-button"]').click();

    // Verify error banner is hidden
    cy.get('[data-testid="error-banner"]').should('not.exist');

    // Verify error state is cleared from UI
    cy.get('[data-testid="error-state-indicator"]').should('not.exist');

    // Verify user can still interact with the page
    cy.get('[data-testid="refresh-button"]').should('be.visible');
    cy.get('[data-testid="refresh-button"]').click();
  });
});
